/* Expense module layout and entry form aligned with the supplied demo screens. */
(function(){
  let expenseCategoryFilter='',expenseFrom='',expenseTo='';
  const demoExpenseCategories=['Salary','Shop Rent','Electricity Bill','Tea & Snacks','Mechanic Allowance','Tools & Equipment','Internet Bill','Water Bill','Miscellaneous'];
  db.lists['Expense Categories']=db.lists['Expense Categories']||[];
  for(const category of demoExpenseCategories)if(!db.lists['Expense Categories'].some(item=>item.toLowerCase()===category.toLowerCase()))db.lists['Expense Categories'].push(category);
  const basicPageBeforeExpenseDemo=basicPage;
  const expenseCategories=()=>[...new Set([...(db.lists['Expense Categories']||[]),'Salary'])];
  const expenseMatches=expense=>matches({...expense,staffName:name('staff',expense.staff||'')})&&(!expenseCategoryFilter||expense.category===expenseCategoryFilter)&&(!expenseFrom||expense.date>=expenseFrom)&&(!expenseTo||expense.date<=expenseTo);
  const salaryExpense=expense=>['Salary','Staff Salary / Advance'].includes(expense.category)&&expense.staff;
  function staffSalaryInfo(staffId){
    const staff=find('staff',staffId),items=(db.expenses||[]).filter(salaryExpense).filter(expense=>expense.staff===staffId);
    const advance=items.filter(expense=>expense.salaryPaymentType==='advance').reduce((sum,expense)=>sum+Number(expense.amount||0),0);
    const salaryPaid=items.filter(expense=>expense.salaryPaymentType!=='advance').reduce((sum,expense)=>sum+Number(expense.amount||0),0);
    const entitlement=staff?.salaryType==='Monthly'?Number(staff.salary||0):0;
    return {staff,advance,salaryPaid,entitlement,due:Math.max(0,entitlement-advance-salaryPaid)};
  }
  function staffSalarySummary(staffId){
    if(!staffId)return '<div class="staffSalarySummary empty">Select a staff member to view salary advance and due information.</div>';
    const info=staffSalaryInfo(staffId);if(!info.staff)return '';
    const entitlement=info.staff.salaryType==='Monthly'?money(info.entitlement):`${info.staff.salary||0}% per job`;
    const due=info.staff.salaryType==='Monthly'?money(info.due):'Calculated per job card';
    return `<div class="staffSalarySummary"><div><small>STAFF MEMBER</small><b>${esc(info.staff.name)}</b></div><div><small>SALARY / RATE</small><b>${entitlement}</b></div><div><small>ADVANCE PAID</small><b>${money(info.advance)}</b></div><div><small>SALARY PAID</small><b>${money(info.salaryPaid)}</b></div><div class="due"><small>BALANCE DUE</small><b>${due}</b></div></div>`;
  }
  function expensePage(){
    const rows=(db.expenses||[]).filter(expenseMatches);
    const total=(db.expenses||[]).reduce((sum,expense)=>sum+Number(expense.amount||0),0);
    const thisMonth=(db.expenses||[]).filter(expense=>String(expense.date||'').startsWith(today().slice(0,7))).reduce((sum,expense)=>sum+Number(expense.amount||0),0);
    const todayTotal=(db.expenses||[]).filter(expense=>expense.date===today()).reduce((sum,expense)=>sum+Number(expense.amount||0),0);
    return `<section class="expensesDemoPage"><div class="expensesDemoIntro"><h2>${icon('wallet')} Garage Expenses Management</h2><p>Track daily operational expenditure logs, shop rent, electricity, tea, tools, salary and petty-cash outflows.</p><div class="expensesDemoActions"><button type="button" class="btn expenseAddButton" data-expense-demo-add>${icon('plus')}Add Expense</button><button type="button" class="btn success exportButton" data-action="export">${icon('download')}Export Excel</button><button type="button" class="btn printButton" data-expense-demo-print>${icon('print')}Print List</button></div></div>`+
      `<div class="expenseKpis"><article><small>TOTAL EXPENSES</small><strong>${money(total)}</strong></article><article><small>THIS MONTH EXPENSES</small><strong>${money(thisMonth)}</strong></article><article><small>TODAY'S EXPENSES</small><strong>${money(todayTotal)}</strong></article><article><small>TOTAL ENTRIES</small><strong>${db.expenses.length} Entries</strong></article></div>`+
      `<div class="expenseFilters"><input id="search" class="search" type="search" placeholder="Search category, description, payment mode..." aria-label="Search expenses" value="${esc(search)}"><select id="expenseCategoryFilter" aria-label="Filter expense category"><option value="">-- All Categories --</option>${opts(expenseCategories(),expenseCategoryFilter)}</select><label>From:<input id="expenseFrom" type="date" value="${esc(expenseFrom)}"></label><label>To:<input id="expenseTo" type="date" value="${esc(expenseTo)}"></label><button type="button" class="btn secondary" data-expense-demo-reset>↻ Reset</button></div>`+
      table(['Expense ID','Date','Category','Amount (₹)','Payment Mode','Paid From Account','Description','Actions'],rows.map(expense=>[esc(expense.id),esc(expense.date),badge(expense.category),money(expense.amount),esc(expense.mode||'—'),esc(name('accounts',expense.account)||'—'),`${esc(expense.description||'—')}${expense.staff?`<small>Staff: ${esc(name('staff',expense.staff))} · ${expense.salaryPaymentType==='advance'?'Salary Advance':'Salary Payment'}</small>`:''}`,`<div class="rowactions"><button type="button" class="btn small editButton" data-expense-demo-edit="${esc(expense.id)}" title="Edit expense">${icon('edit')}</button><button type="button" class="btn small deleteButton" data-delete="expenses|${esc(expense.id)}" title="Delete expense">${icon('trash')}</button></div>`]));
  }
  basicPage=function(key){return key==='expenses'?expensePage():basicPageBeforeExpenseDemo(key)};

  function expenseForm(id){
    const record=id?structuredClone(find('expenses',id)):{id:nextId('expenses'),category:'',amount:0,date:today(),mode:'Cash',account:db.accounts.find(account=>account.status!=='Inactive')?.id,description:'',staff:''};
    const isSalary=()=>['Salary','Staff Salary / Advance'].includes(form.querySelector('[name="category"]').value);
    openModal(id?'Edit Expense':'Add New Expense',`<form id="expenseDemoForm"><div class="formbody"><div class="expenseFormTop"><label class="field"><span>Category <b class="required">*</b></span><div class="expenseCategoryChoice"><select name="category" required>${opts(expenseCategories(),record.category)}</select><button type="button" class="btn small" id="expenseCategoryAdd" title="Add expense category">${icon('plus')}</button></div></label></div><section id="expenseSalaryDetails" class="expenseSalaryDetails" hidden><div><strong>${icon('users')} Staff Salary Details & Attendance Calculation</strong><span>Cumulative / All-Time</span></div><div class="formgrid"><label class="field"><span>Select Staff Member <b class="required">*</b></span><select name="staff"><option value="">-- Select Staff Member --</option>${opts(reference('staff'),record.staff)}</select></label><label class="field"><span>Salary Payment Type <b class="required">*</b></span><select name="salaryPaymentType">${opts([{value:'advance',label:'Salary Advance'},{value:'salary',label:'Full / Balance Salary Payment'}],record.salaryPaymentType||'salary')}</select></label></div><div id="staffSalarySummary"></div></section><div class="formgrid">${field({key:'amount',label:'Amount (₹)',type:'number',required:true},record)}${field({key:'date',label:'Date',type:'date',required:true},record)}${field({key:'mode',label:'Payment Mode',type:'select',options:list('Payment Modes'),required:true},record)}${field({key:'account',label:'Paid From Account',type:'select',options:()=>reference('accounts'),required:true},record)}${field({key:'description',label:'Description',type:'textarea',full:true},record)}</div></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button class="btn" type="submit">${icon('check')}Save Expense</button></div></form>`);
    const form=$('#expenseDemoForm'),salaryPanel=$('#expenseSalaryDetails'),staffSelect=form.querySelector('[name="staff"]'),salarySummary=$('#staffSalarySummary');
    const refreshSalarySummary=()=>{salarySummary.innerHTML=staffSalarySummary(staffSelect.value)};
    const toggleSalary=()=>{salaryPanel.hidden=!isSalary();staffSelect.required=isSalary();if(isSalary())refreshSalarySummary()};
    form.querySelector('[name="category"]').onchange=toggleSalary;staffSelect.onchange=refreshSalarySummary;toggleSalary();
    $('#expenseCategoryAdd').onclick=()=>{const value=window.prompt('New expense category name:','');if(!value?.trim())return;const label=value.trim();if(!db.lists['Expense Categories'].some(item=>item.toLowerCase()===label.toLowerCase()))db.lists['Expense Categories'].push(label);const select=form.querySelector('[name="category"]');select.innerHTML=opts(expenseCategories(),label);toggleSalary()};
    form.onsubmit=async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(form));data.amount=Number(data.amount);if(!data.category||!Number.isFinite(data.amount)||data.amount<=0)return toast('Enter a category and an amount greater than zero.');if(['Salary','Staff Salary / Advance'].includes(data.category)&&!data.staff)return toast('Select the staff member for a salary expense.');const button=form.querySelector('[type="submit"]');button.disabled=true;try{await window.saveCloudExpense(id,{...record,...data});save();if(form.isConnected)closeModal();render();toast('Expense saved to Cloudflare D1.')}catch(error){toast(error.message)}finally{button.disabled=false}};
  }
  document.addEventListener('click',event=>{const add=event.target.closest('[data-expense-demo-add]'),edit=event.target.closest('[data-expense-demo-edit]'),print=event.target.closest('[data-expense-demo-print]'),reset=event.target.closest('[data-expense-demo-reset]');if(add){event.preventDefault();expenseForm();}if(edit){event.preventDefault();expenseForm(edit.dataset.expenseDemoEdit)}if(print){event.preventDefault();openModal('Expenses List',`<div class="invoice"><h2>${esc(db.settings.name)} — Expenses List</h2><p>Printed on ${esc(today())}</p>${$('#content .tablewrap')?.outerHTML||''}</div><div class="formactions">${btn('Close','cancel','secondary')}${btn('Print / Save PDF','print','','print')}</div>`)}if(reset){event.preventDefault();expenseCategoryFilter='';expenseFrom='';expenseTo='';search='';render()}});
  const renderBeforeExpenseDemo=render;
  render=function(){renderBeforeExpenseDemo();if(page!=='expenses')return;const category=$('#expenseCategoryFilter'),from=$('#expenseFrom'),to=$('#expenseTo');if(category)category.onchange=event=>{expenseCategoryFilter=event.target.value;render()};if(from)from.onchange=event=>{expenseFrom=event.target.value;render()};if(to)to.onchange=event=>{expenseTo=event.target.value;render()}};
})();
